        return 'Error: Invalid file path';
    }

    try {
        const fileContent = fs.readFileSync(normalizedPath, 'utf8');
        const yamlData = yaml.load(fileContent);
        return JSON.stringify(yamlData);
    } catch (error) {
        return `Error: ${error.message}`;
    }
}
